<?php
 namespace Pterodactyl\Jobs\Dezerx; use Throwable; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\User; use Pterodactyl\Models\Backup; use Pterodactyl\Models\Server; use Pterodactyl\Exceptions\DisplayException; use Symfony\Component\HttpKernel\Exception\HttpExceptionInterface; use Illuminate\Support\Facades\Log; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Pterodactyl\Models\Dezerx\DriveBackup; use Illuminate\Queue\Middleware\WithoutOverlapping; use Pterodactyl\Services\Dezerx\Drive\GoogleDrive; use Pterodactyl\Services\Dezerx\Drive\DriveBackups; use Pterodactyl\Services\Backups\DeleteBackupService; use Pterodactyl\Services\Backups\DownloadLinkService; class CopyBackupToDrive extends Job implements ShouldQueue { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 7200; public int $tries = 1; private const BACKUP_WAIT_SECONDS = 3600; private ?Server $server = null; private ?User $owner = null; private ?Backup $taken = null; public function __construct(public DriveBackup $link, public bool $manual = false) { $this->onQueue('standard'); } public function middleware(): array { return [(new WithoutOverlapping('drive:' . $this->link->server_id))->releaseAfter(60)->expireAfter($this->timeout + 60)]; } public function handle(): void { $this->mark('running', 'Preparing a backup.'); try { $drive = GoogleDrive::forRefreshToken($this->link->refresh_token); if ($drive === null) { $this->mark('failed', 'That Google account is no longer connected. Reconnect it.'); return; } $backup = $this->backup(); if ($backup === null) { $this->mark('failed', 'No backup could be made to copy.'); return; } $folder = $drive->folder($this->folderName(), $this->link->folder_id); if ($folder === null) { $this->mark('failed', $this->because('The Drive folder could not be opened', $drive->lastError())); return; } if ($folder !== $this->link->folder_id) { $this->link->forceFill(['folder_id' => $folder])->saveOrFail(); } $this->mark('running', "Uploading {$backup->name}."); $url = app(DownloadLinkService::class)->handle($backup, $this->owner()); $name = $this->fileName($backup); if ($drive->upload($url, $folder, $name, $backup->bytes) === null) { $this->mark('failed', $this->because('The upload to Google Drive did not finish', $drive->lastError())); return; } $removed = $this->prune($drive, $folder); $tidied = $this->tidy(); $this->mark( 'done', 'Copied ' . $name . ' to Drive.' . ($removed > 0 ? " Removed {$removed} older " . ($removed === 1 ? 'copy' : 'copies') . ' from Drive.' : '') . ($tidied ? ' The server has no room to keep backups, so its local copy was removed.' : '') ); } catch (DisplayException|HttpExceptionInterface $exception) { $this->log($exception); $said = trim($exception->getMessage()); $this->mark('failed', $said !== '' ? $said : 'That backup could not be copied to Drive. The panel log has the reason.'); } catch (Throwable $exception) { $this->log($exception); report($exception); $this->mark('failed', 'That backup could not be copied to Drive. The panel log has the reason.'); } } public function failed(?Throwable $exception): void { $this->mark('failed', 'Copying to Drive took too long and was stopped.'); } private function server(): Server { return $this->server ??= Server::query()->findOrFail($this->link->server_id); } private function owner(): User { return $this->owner ??= User::query()->findOrFail($this->link->user_id); } private function backup(): ?Backup { $newest = $this->server()->backups() ->whereNotNull('completed_at') ->whereNull('deleted_at') ->where('is_successful', true) ->orderByDesc('created_at') ->first(); $hours = max(1, $this->link->interval_hours); if ($newest !== null && $newest->created_at->addHours($hours)->isFuture()) { return $newest; } $this->mark('running', 'Taking a fresh backup.'); $this->taken = app(DriveBackups::class) ->take($this->server(), 'Google Drive ' . now()->format('Y-m-d H:i')); return $this->await($this->taken); } private function await(Backup $backup): ?Backup { $deadline = microtime(true) + self::BACKUP_WAIT_SECONDS; do { sleep(10); $backup->refresh(); if ($backup->completed_at !== null) { return $backup->is_successful ? $backup : null; } } while (microtime(true) < $deadline); Log::warning('Drive backup: the server never finished its backup', [ 'server' => $this->server()->uuid, 'backup' => $backup->uuid, ]); return null; } private function tidy(): bool { if ($this->taken === null || !app(DriveBackups::class)->overLimit($this->server())) { return false; } try { app(DeleteBackupService::class)->handle($this->taken); } catch (Throwable $exception) { $this->log($exception); return false; } return true; } private function prune(GoogleDrive $drive, string $folder): int { $files = $drive->contents($folder); if (count($files) <= $this->link->keep) { return 0; } $removed = 0; foreach (array_slice($files, $this->link->keep) as $file) { if ($drive->delete($file['id'])) { $removed++; } } return $removed; } private function folderName(): string { return 'Pterodactyl · ' . $this->server()->name; } private function fileName(Backup $backup): string { $stamp = ($backup->created_at ?? now())->format('Y-m-d_His'); return sprintf('%s_%s_%s.tar.gz', $this->server()->uuidShort, $stamp, substr($backup->uuid, 0, 8)); } private function because(string $what, ?string $reason): string { return $reason === null ? $what . '.' : $what . ', because ' . $reason; } private function log(Throwable $exception): void { try { Log::warning('Drive backup failed', [ 'server' => $this->link->server_id, 'link' => $this->link->id, 'exception' => $exception::class, 'message' => $exception->getMessage(), ]); } catch (Throwable) { } } private function mark(string $state, string $message): void { $this->link->forceFill([ 'last_state' => $state, 'last_message' => $message, 'last_run_at' => now(), ])->saveOrFail(); } } 